def palette(colors: dict[str, str]) -> QPalette:
    """Build the palette of one mode."""
    result = QPalette()
    for role, name in ROLES.items():
        result.setColor(role, QColor(colors[name]))
    disabled = QColor(colors["on_surface"])
    disabled.setAlphaF(0.38)
    for role in (
        QPalette.ColorRole.WindowText,
        QPalette.ColorRole.Text,
        QPalette.ColorRole.ButtonText,
    ):
        result.setColor(QPalette.ColorGroup.Disabled, role, disabled)
    return result
